INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000014','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Dans quels cas doit-on se rendre aux urgences hospitalières ?','Les urgences sont réservées aux situations médicales graves, soudaines ou potentiellement dangereuses : douleur thoracique, perte de connaissance, hémorragie, trauma sérieux. Pour les soins non urgents, voir le médecin traitant ou SOS Médecins.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000015','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Pourquoi certaines vaccinations sont-elles obligatoires en France ?','Les vaccinations obligatoires protègent l''individu et l''ensemble de la population (immunité collective). Depuis 2018, 11 vaccins sont obligatoires pour les nourrissons (rougeole, tétanos, etc.).','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000016','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À quoi sert la carte Vitale en France ?','La carte Vitale prouve l''affiliation à la Sécurité sociale. Elle permet aux professionnels de santé de transmettre les feuilles de soins électroniquement et d''être remboursé rapidement.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000017','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À quoi sert une complémentaire santé (mutuelle) ?','La mutuelle complète les remboursements de la Sécurité sociale (qui ne rembourse pas toujours 100% des frais). Elle peut couvrir des soins comme l''optique, le dentaire, l''audioprothèse.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000018','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Jusqu''à quel âge l''instruction est-elle obligatoire en France ?','L''instruction est obligatoire jusqu''à 16 ans (loi de 1959, abaissée à 3 ans en 2019). L''obligation de formation a été instaurée jusqu''à 18 ans depuis 2020.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000019','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Que prévoit l''autorité parentale en France ?','L''autorité parentale impose aux parents (ensemble en général) de protéger, éduquer, nourrir et soigner leur enfant mineur, jusqu''à sa majorité ou son émancipation.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000001a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Pour quels enfants l''école est-elle obligatoire ?','L''instruction est obligatoire pour tous les enfants de 3 à 16 ans résidant en France, quelle que soit leur nationalité (française ou étrangère).','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000001b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel diplôme obtient-on à la fin du lycée général ou technologique ?','Le baccalauréat (général, technologique ou professionnel) est le diplôme obtenu en fin de lycée. Il permet d''accéder à l''enseignement supérieur.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000001c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Après l''école élémentaire, dans quel établissement vont les élèves ?','Après l''école élémentaire (CP à CM2), les élèves entrent au collège (6e à 3e), puis au lycée (2nde à Terminale). Le collège accueille tous les enfants jusqu''au brevet.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000001d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Pour quels élèves l''école publique est-elle obligatoire ?','L''instruction (à l''école, en famille avec contrôle, ou en établissement privé) est obligatoire pour tous les enfants de 3 à 16 ans résidant en France, sans distinction.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000001e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Que prévoit l''inscription d''un enfant à l''école ?','L''inscription à l''école publique se fait à la mairie (puis à l''école). Elle implique des droits (instruction gratuite, restauration scolaire) et des obligations (assiduité, respect du règlement).','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000001f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Que prévoit l''école pour les enfants qui ne parlent pas français à leur arrivée ?','L''Éducation nationale propose un accompagnement spécifique : UPE2A (unité pédagogique pour élèves allophones arrivants), enseignants formés au FLE/FLS, soutien linguistique adapté.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000001','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne la ''CAF'' en France ?','La CAF (Caisse d''allocations familiales) verse des prestations aux familles : allocations familiales, prime d''activité, aide au logement (APL), RSA, etc.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000002','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que sont les APL ?','Les Aides personnalisées au logement (APL) sont des allocations versées par la CAF aux personnes à faibles revenus pour les aider à payer leur loyer ou leur emprunt immobilier.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000003','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne le RSA en France ?','Le RSA (Revenu de solidarité active) est une allocation versée aux personnes sans ressources ou aux faibles revenus, pour leur garantir un revenu minimum.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000004','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','À qui faut-il s''adresser pour obtenir un logement social ?','Pour un logement social (HLM), on dépose un dossier en mairie ou auprès d''un bailleur social. Les demandes sont examinées selon des critères sociaux et de revenus.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000005','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Qu''est-ce qu''un HLM ?','Un HLM (Habitation à loyer modéré) est un logement social, dont le loyer est plafonné et dont l''attribution est réservée aux personnes aux revenus modestes.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000006','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel âge minimum pour passer le permis de conduire (B) ?','Le permis B se passe à partir de 17 ans en conduite accompagnée, et 18 ans en filière classique. Pour conduire seul, il faut 18 ans dans tous les cas.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000007','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que représente le ''titre de séjour'' pour un étranger en France ?','Le titre de séjour (carte de séjour) est un document qui autorise un étranger non européen à séjourner régulièrement en France. Il existe plusieurs types (étudiant, salarié, vie privée, résident).','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000008','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel âge marque l''entrée au collège en France ?','L''entrée au collège se fait normalement à 11 ans, en classe de 6e, après la fin de l''école élémentaire (CM2). Le collège se termine en 3e avec le brevet.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000009','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Combien y a-t-il d''années au collège ?','Le collège dure 4 ans : 6e, 5e, 4e, 3e. A la fin de la 3e, les élèves passent le diplôme national du brevet (DNB).','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000000a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel diplôme obtient-on à la fin du collège ?','Le brevet (Diplôme national du brevet, DNB) est l''examen passé en fin de 3e, à 14-15 ans. C''est le premier diplôme de la scolarité obligatoire.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000000b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','À quel âge commence l''école obligatoire en France ?','Depuis 2019, l''instruction est obligatoire dès 3 ans (auparavant 6 ans). C''est l''école maternelle qui débute donc l''instruction obligatoire.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000000c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne la cantine scolaire en France ?','La cantine scolaire est le service de restauration proposé dans les écoles. Elle est généralement gérée par la commune. Son coût est souvent ajusté selon les revenus des familles.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000000d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','L''école publique en France est-elle laïque ?','Oui. L''école publique est laïque depuis les lois Ferry (1881-1882). Cela signifie qu''elle est neutre vis-à-vis des religions et qu''il est interdit d''y afficher des signes religieux ostensibles.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000000e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne-t-on par ''mariage civil'' en France ?','Le mariage civil est l''union légale célébrée par un officier d''état civil (maire ou adjoint) à la mairie. C''est le seul mariage reconnu par l''État français. Un mariage religieux n''a pas de valeur civile.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000000f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne le PACS ?','Le PACS (Pacte civil de solidarité) est un contrat conclu entre deux personnes majeures pour organiser leur vie commune. C''est une alternative au mariage, sans toutes ses formalités.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000010','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que fait un pharmacien en France ?','Le pharmacien dispense les médicaments en officine, conseille les patients, peut effectuer certaines vaccinations (grippe, COVID), réaliser des tests rapides, accompagner les traitements.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000011','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel professionnel donne les premiers soins en cabinet de ville ?','Le médecin généraliste (médecin traitant) est le premier interlocuteur en ville. Il diagnostique, soigne, oriente vers les spécialistes. C''est le pivot du parcours de soins.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000012','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Le tabac est-il interdit aux mineurs en France ?','Oui. La vente de tabac aux mineurs (moins de 18 ans) est interdite. Le commerçant peut être sanctionné. La consommation par les mineurs est très déconseillée.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000013','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel numéro appeler en cas de problème avec un enfant (urgence non vitale) ?','Le 119 est le numéro national ''Allo Enfance en danger'', gratuit, accessible 24h/24, pour signaler une situation d''enfance en difficulté ou en danger. En cas d''urgence vitale, appeler le 15.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000014','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel sigle désigne l''école en France pour les enfants de 3-5 ans ?','L''école maternelle accueille les enfants de 3 à 5/6 ans (petite, moyenne et grande section). Elle précède l''école élémentaire et est obligatoire depuis 2019.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000015','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne la ''crèche'' en France ?','La crèche est un mode de garde collectif pour les enfants de 0 à 3 ans environ. Les places sont attribuées par la mairie ou des structures privées. Le tarif dépend des revenus des parents.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000016','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Le mariage en France est-il privé ou public ?','Le mariage civil est célébré publiquement à la mairie, généralement dans la salle des mariages. Tout citoyen peut y assister. Le mariage est inscrit à l''état civil.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000017','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Qu''est-ce que le ''parcours du combattant'' administratif ?','L''expression décrit (informellement) les nombreuses démarches administratives parfois complexes (cartes d''identité, permis, allocations, retraites). Le site service-public.fr regroupe les démarches.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000018','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Comment s''appelle le document officiel d''état civil prouvant la naissance ?','L''acte de naissance est le document officiel établi par la mairie à la déclaration de naissance. Il est ensuite nécessaire pour de nombreuses démarches (carte d''identité, passeport, mariage).','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000019','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel document atteste de la nationalité française ?','La carte nationale d''identité et le passeport prouvent la nationalité française. Un certificat de nationalité française (CNF) peut aussi être délivré par les tribunaux.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000001a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel âge permet de quitter le foyer parental ?','À 18 ans (majorité légale), une personne peut quitter le foyer familial sans autorisation. Avant, l''émancipation est possible dès 16 ans, mais elle est encadrée.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000001b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Le voyage en avion nécessite-t-il un document d''identité ?','Oui. Pour tout voyage en avion (intérieur ou international), il faut présenter une pièce d''identité (carte d''identité, passeport). Pour l''international hors UE, un passeport est généralement obligatoire.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000001c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel âge minimum pour entrer en boîte de nuit en France ?','L''accès aux boîtes de nuit est généralement réservé aux personnes majeures (18 ans). Certains établissements peuvent fixer un âge plus élevé. La vente d''alcool aux mineurs est interdite.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000001d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','À quoi servent les transports en commun urbains (bus, métro) ?','Les transports en commun urbains permettent de circuler en ville. Ils sont gérés par les autorités locales et offrent des tarifs réduits pour les jeunes, retraités, étudiants, demandeurs d''emploi.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000001e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne l''INSEE ?','L''INSEE (Institut national de la statistique et des études économiques) produit les statistiques officielles de la France : population, économie, emploi, prix.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000001f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel établissement gère le prêt de livres gratuitement ?','La bibliothèque (ou médiathèque municipale) permet d''emprunter gratuitement des livres, parfois des CD/DVD, et offre l''accès à internet. L''inscription est généralement peu chère ou gratuite.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000020','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel âge permet de passer le permis de conduire la moto (A1) ?','Le permis A1 (motos de 125 cm3 maximum) peut être passé à partir de 16 ans. Le permis A2 (moto plus puissante) requiert 18 ans, le permis A (toute moto) 24 ans (ou 20 ans avec A2 pendant 2 ans).','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000021','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Le port du casque est-il obligatoire à vélo en France ?','Le port du casque à vélo est obligatoire pour les enfants de moins de 12 ans (conducteur ou passager). Pour les adultes, il est seulement recommandé mais très conseillé.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000022','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel objet est obligatoire dans une voiture en France ?','Les véhicules doivent posséder : un gilet jaune fluorescent, un triangle de signalisation, ainsi qu''un éthylotest (officiellement). Le constat amiable est aussi essentiel.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000023','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel numéro composer pour les renseignements téléphoniques administratifs ?','Le 39 39 (Allo service public) renseigne sur les démarches administratives. Service au coût d''un appel local depuis un fixe.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000024','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne la ''pièce d''identité'' en France ?','Une pièce d''identité (carte nationale d''identité, passeport, titre de séjour) est un document officiel avec photo, permettant de prouver son identité. Elle peut être exigée dans de nombreuses situations.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000025','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Combien de temps est valable une carte nationale d''identité française ?','Une carte nationale d''identité française est valable 15 ans pour les majeurs (depuis 2014), 10 ans pour les mineurs. Pour voyager hors UE, certains pays exigent une carte non périmée.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000026','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Qu''est-ce qu''un ''centre des impôts'' en France ?','Le centre des impôts (ou service des impôts des particuliers) est l''administration qui gère la fiscalité des particuliers : déclaration de revenus, impôt sur le revenu, impôts locaux.','true','2026-05-27 17:40:30.089544+02',NULL,'ACTIVE',NULL,NULL,NULL);
